        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = DateTime.UtcNow });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// Cosmos DB context demonstrating EF Core 9 breaking change fixes
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "CatalogDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // BREAKING CHANGE 1: EF Core 9 renamed "Discriminator" to "$type" by default.
        // To keep reading existing documents that use "Discriminator", set it explicitly:
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

        modelBuilder.Entity<Product>().ToContainer("Products");
        modelBuilder.Entity<Product>().HasPartitionKey(p => p.Category);
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
}

// BREAKING CHANGE 2: Synchronous Cosmos DB queries now throw by default in EF Core 9.
// All queries must use async methods (ToListAsync, FirstOrDefaultAsync, etc.).
class CosmosQueryService
{
    // BEFORE (EF Core 8 — sync was allowed):
    // var items = db.Products.Where(p => p.Category == "Books").ToList();

    // AFTER (EF Core 9 — must use async):
    public async Task<List<Product>> GetProductsAsync(CosmosDbContext db)
    {
        return await db.Products
            .Where(p => p.Category == "Books")
            .ToListAsync();
    }
}

